"""Read-only documentary/result review; no FK, fitting or geometry imports."""
from pathlib import Path
import json,hashlib,datetime
OUT=Path(__file__).parent;DOC=Path('/private/tmp/hug_criteria_alignment_root_2026-10-15_v1');FIT=Path('/private/tmp/hug_feasibility_restoration_2026-10-15_v1')
def read(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
docs=[DOC/n for n in ['criteria_alignment.md','paper_scope_paragraph.tex','paper_result_paragraph.tex']]
texts={p.name:p.read_text() for p in docs}
assert 'These are counts of checkpoints failing retained-row checks' in texts['criteria_alignment.md']
assert 'These are retained-row counts' not in texts['criteria_alignment.md']
assert 'source-reach-derived translation boxes' in texts['criteria_alignment.md']
cp=FIT/'candidate_targets.json';c=read(cp);eps=[r for x in c['cases'] for r in x['restoration_endpoint_results']]
assert len(c['cases'])==6 and len(eps)==12
counts={'reported_restored_tip_feasible':sum(r['exact_surface_check']['tip_status']['passed'] for r in eps),'tip_FK_callbacks':sum(r['counts']['FK_executions'] for r in eps),'analytic_Jacobian_callbacks':sum(r['counts']['analytic_jacobian_executions'] for r in eps),'actual_projection_mj_forward_calls':sum(r['actual_projection_mj_forward_calls'] for r in eps),'retained_surface_checks':sum(x['exact_surface_checks'] for x in c['cases']),'eligible_coarse_candidates':sum(x['eligible_for_limited_coarse_audit'] for x in c['cases'])}
assert counts=={'reported_restored_tip_feasible':12,'tip_FK_callbacks':1101,'analytic_Jacobian_callbacks':161,'actual_projection_mj_forward_calls':2524,'retained_surface_checks':24,'eligible_coarse_candidates':0}
assert counts['actual_projection_mj_forward_calls']==2*(counts['tip_FK_callbacks']+counts['analytic_Jacobian_callbacks'])
reason_counts={r:sum(r in e['improvement_gate']['refusal_reasons'] for e in eps) for r in ['no_strict_original_rank_improvement','previously_valid_orientation_row_invalidated','previously_passed_orientation_row_failed']}
assert list(reason_counts.values())==[12,10,6]
m=next(x for x in c['cases'] if x['source_inventory_index']==24);endpoint=m['restoration_endpoint_results'][0]['exact_surface_check'];ref=m['reference_constraint_diagnostics']
mug={'case_index':24,'endpoint_start_index':0,'restored_passed_proximity_rows':sum(endpoint['proximity']['passed']),'proximity_rows':len(endpoint['proximity']['passed']),'reference_passed_proximity_rows':sum(ref['proximity']['passed']),'reference_max_normalized_violation':ref['rank'][2],'restored_max_normalized_violation':endpoint['rank'][2],'retained_orientation_rows':len(endpoint['exact_orientation']['passed'])}
assert mug=={'case_index':24,'endpoint_start_index':0,'restored_passed_proximity_rows':11,'proximity_rows':57,'reference_passed_proximity_rows':10,'reference_max_normalized_violation':5.0,'restored_max_normalized_violation':5.445342574151935,'retained_orientation_rows':0}
assert all(x['audited_pose_role']=='pooled_reference_retained' for x in c['cases'])
skip_path=Path('/private/tmp/hug_feasibility_restoration_audit_2026-10-15_v1/audit_skip_receipt.json');skip=read(skip_path)
assert skip['saved_output_checks_passed']==226 and skip['fresh_coarse_grids']==skip['fresh_fine_grids']==0 and skip['historical_evidence']['strict_failure_comparisons']==9
support=[cp,FIT/'protocol.json',skip_path,Path('/private/tmp/hug_criteria_provenance_2026-10-15_v1/evidence.json'),Path('/private/tmp/hug_criteria_provenance_2026-10-15_v1/criteria.json'),Path('/private/tmp/hug_criteria_provenance_2026-10-15_v1/root_draft_review.json'),Path('/private/tmp/hug_surface_constraints_audit_2026-10-15_v1/summary.json')]
report={'schema':'hug_current_root_documents_local_provenance_and_result_review_v1','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'passed':True,'reviewed_document_bindings':{str(p):sha(p) for p in docs},'evidence_bindings':{str(p):sha(p) for p in support},'scope':'Current root clarification and manuscript paragraphs reviewed against local criteria provenance and saved-output restoration arithmetic/226-check gate replay. No independent external-paper reread or repeated FK/geometry. External HUG benchmark/exporter facts remain the separate root source review responsibility.','resolved_findings':[{'topic':'count denominator','prior_issue':'Ten and six count restored checkpoints failing retained-row gates, not rows.','resolution':'Clarification now explicitly says counts of checkpoints failing retained-row checks.'},{'topic':'translation-domain provenance','resolution':'Clarification now names source-reach-derived translation boxes separately from the ±0.35rad joint search choice.'}],'blocking_findings':[],'review_conclusions':['Project engineering guards are distinguished from paper thresholds and implementation correctness.','Strict failures retain their claim/domain and are not used to assert every approximate Shadow pipeline is unusable.','Native-target fingertip error is distinguished from fingertip-to-object quality.','Literal individual-collider distance surfaces are distinguished from exposed boundary/active contact geometry.','Identity-certificate uncertainty does not invalidate definite counterexamples.','Practical acceptance remains prospective, with no newly selected thresholds or retrospective passing label.','Reported restoration callback totals, fixed reference counts and Mug A tradeoff agree with saved outputs.','Orientation invalidation is distinguished from measured sign reversal; projection causality is not asserted.','All six retained reference poses and zero fresh grids are reported; historical nine failures are not described as rerun.','No global projection optimality, full mapping acceptance or downstream generalization is claimed.'],'verified_saved_output_counts':counts,'refusal_counts_of_checkpoints_overlapping':reason_counts,'mug_a_saved_row_comparison':mug,'fresh_surface_queries':0,'new_FK':0,'physics_steps':0,'new_eval_data':False,'shared_edits':False}
p=OUT/'final_root_review.json';assert not p.exists();p.write_text(json.dumps(report,indent=2)+'\n')
files=[{'path':p.name,'size_bytes':p.stat().st_size,'sha256':sha(p)} for p in sorted(OUT.iterdir()) if p.is_file() and p.name!='manifest.json']
(OUT/'manifest.json').write_text(json.dumps({'schema':'hug_current_root_document_review_manifest_v1','files':files},indent=2)+'\n')
print(json.dumps({'passed':True,'review_sha256':sha(OUT/'final_root_review.json'),'manifest_sha256':sha(OUT/'manifest.json'),'document_hashes':report['reviewed_document_bindings']},indent=2))
